from sqlalchemy.inspection import inspect
from zou.app.utils.fields import serialize_value


class SerializerMixin(object):

    def serialize(self):
        attrs = inspect(self).attrs.keys()
        return {
            "type": self.__class__.__name__,
            "attributes": {
                attr: serialize_value(getattr(self, attr)) for attr in attrs
            }
        }

    @staticmethod
    def serialize_list(models):
        return [model.serialize() for model in models]

def checkio(array):

    def if_win(value, pos):
        if array[pos[0]][pos[1]] == value:
            return True
        return False

    for i in range(3):
        # Check rows
        if if_win("X", (i, i)):
            if if_win("X", (i, i+1)):
                if if_win("X", (i, i+2)):
                    return "X"
        # Check columns
        if if_win("X", (i, i)):
            if if_win("X", (i+1, i)):
                if if_win("X", (i+2, i)):
                    return "X"
        # Check diagonals
        if if_win("X", (i, 2-i)):
            if if_win("X", (i+1, 1-i)):
                if if_win("X", (i+2, -i)):
                    return "X"

    for i in range(3):
        # Check rows
        if if_win("O", (i, i)):
            if if_win("O", (i, i+1)):
                if if_win("O", (i, i+2)):
                    return "O"
        # Check columns
        if if_win("O", (i, i)):
            if if_win("O", (i+1, i)):
                if if_win("O", (i+2, i)):
                    return "O"
        # Check diagonals
        if if_win("O", (i, 2-i)):
            if if_win("O", (i+1, 1-i)):
                if if_win("O", (i+2, -i)):
                    return "O"

    return "D"

if __name__ == '__main__':
    assert checkio([
    "X.O",
    "XX.",
    "XOO"]) == "X", "Xs wins"
    assert checkio([
    "OO.",
    "XOX",
    "XOX"]) == "O", "Os wins"
    assert checkio([
    "OOX",
    "XXO",
    "OXX"]) == "D", "Draw"

