    #print(data)
    if all(i == value for i in data):
        return "W"
    # check 2 liners from left-top corner to right-bottom corner
    data = get_data_by_number(get_3linelist(2), value)
    #print(data)
    if all(i == value for i in data):
        return "W"
    # check 2 liners from right-top corner to left-bottom corner
    data = get_data_by_number(get_3linelist(3), value)
    if all(i == value for i in data):
        return "W"

    return "L"

def get_3linelist(Number):
    matrix = [[(x, y) for x in range(3)] for y in range(3)]
    if Number == 0:
        return matrix
    elif Number == 1:
        return [[(y, x) for x in range(3)] for y in range(3)]
    elif Number == 2:
        return [[[0, 0], [1, 1], [2, 2]], [[0, 2], [1, 1], [2, 0]]]
    elif Number == 3:
        return [[[0, 1], [1, 1], [2, 1]], [[1, 0], [1, 1], [1, 2]]]

def get_data_by_number(Select, value):
    data = []
    for items in Select:
        for item in items:
            if item[0] != item[1]:
                value = "D"
            elif item[0] == item[1]:
                pass
            elif item[0] == value:
                pass
            elif item[1] == value:
                pass
            else:
                value = "D"
        if all(i == value for i in data):
            break
        data.append(value)
    return data

if __name__ == '__main__':
    assert checkio([
    "X.O",
    "XX.",
    "XOO"]) == "X", "Xs wins"
    assert checkio([
    "OO.",
    "XOX",
    "XOX"]) == "O", "Os wins"
    assert checkio([
    "OOX",
    "XXO",
    "OXX"]) == "D", "Draw"

