from .node_mixins import Load, Copy


class Node(object):
    def __eq__(self, other):
        return (
            self.__class__ == other.__class__ and
            self.__dict__ == other.__dict__
        )

    def __ne__(self, other):
        return not self == other


class Int(Node):
    def __init__(self, i):
        self.i = i
    def __repr__(self):
        return str(self.i)


class TripleAsterisk(Node, Load, Copy):
    def __repr__(self):
        return "***"


class Tuple(Node, Load, Copy):
    def __init__(self, items):
        self.items = items
    def __repr__(self):
        inner = ", ".join(repr(x) for x in self.items)
        if len(self.items) == 2:
            return "({0}, {1})".format(repr(self.items[0]), repr(self.items[1]))
        elif len(self.items) == 1:
            return "({0},)".format(repr(self.items[0]))
        else:
            return "({0})".format(inner)


class BinOp(Node, Load, Copy):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right
    def __repr__(self):
        return "BinaryOp({0}, {1}, {2})".format(repr(self.op), repr(self.left), repr(self.right))


class Add(Node):
    def __repr__(self):
        return "Plus()"


class Div(Node):
    def __repr__(self):
        return "Div()"


class Call(Node, Load, Copy):
    def __init__(self, rec, args):
        self.rec = rec
        self.args = args
    def __repr__(self):
        args = ", ".join(repr(x) for x in self.args)
        return "Call({0}, [{1}])".format(repr(self.rec), args)

